#!/usr/bin/env python3
import os, sys, shutil
import numpy as np
from joblib import Parallel, delayed

#spec_p = 'spec_pump_01'
get_sig_v = '09'
first = 0# first trajectory = 0
last = 49# last trajectory = 99
head_start = 'Traj_'
head_end = '.out'
target = 'Average_signal_out'
dat_p = ''#'/IP_new/get_vde.out'
plot_script = 'generate_plot_freqs.py'
get_sig = 'get_signal_{}.py'.format(get_sig_v)
pfad = os.getcwd()
tstep = 5 #fs
IP_file = ['rhombus_Energy.out', 2] # Name of file and number of column

def readin_std(name):
    time = []
    sig = []
    with open(name) as f:
        data = f.readlines()
        for i in data:
            s = i.split(' ')
            time.append(float(s[0]))
            sig.append(float(s[1].split('\n')[0]))
    return time, sig

workdir = '{}{}{}{}'.format(head_start, str(0), head_end, dat_p)
shutil.copyfile('{}'.format(get_sig), '{}/{}'.format(workdir, get_sig))
os.chdir(workdir)
os.system('chmod 755 {}'.format(get_sig))
os.system('./{}'.format(get_sig))
times, data = readin_std('signal.out')
os.chdir(pfad)

def col_spec(i):
    workdir = '{}{}{}{}'.format(head_start, str(i), head_end, dat_p)
    shutil.copyfile('{}'.format(get_sig), '{}/{}'.format(workdir, get_sig))
    os.chdir(workdir)
    os.system('chmod 755 {}'.format(get_sig))
    os.system('./{}'.format(get_sig))
    _, datan = readin_std('signal.out')
    os.chdir(pfad)
    return(datan)

datan = Parallel(n_jobs=-1)(delayed(col_spec)(i) for i in range(first, last+1))
data = np.einsum('ij->j', datan)

data_av = np.divide(data, last-first+1)
os.chdir(target)
os.system('truncate -s 0 signal_sum.out')
for i in range(len(data_av)):
    os.system("echo {}\t{} >> signal_sum.out".format(times[i], data_av[i]))

os.system('./{}'.format(plot_script))
